const icons={camera:'M8 6l2-3h4l2 3h4a2 2 0 012 2v11a2 2 0 01-2 2H4a2 2 0 01-2-2V8a2 2 0 012-2z|circle:12,13,4',fast:'M3 5l8 7-8 7zM12 5l8 7-8 7z',skip:'M3 5l11 7-11 7zM19 5v14',menu:'M4 6h16M4 12h16M4 18h16',list:'M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01',chevron:'M9 5l7 7-7 7',close:'M6 6l12 12M18 6L6 18',wing:'M3 19c2-11 7-14 18-14l-4 5-4 1 2 2-5 2 1 2-8 2zM3 21l10-10',shield:'M12 2l8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6',up:'M5 14l7-7 7 7M12 7v14',dash:'M5 12h14'};
function renderIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{const p=icons[el.dataset.icon]||icons.list;el.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true">'+p.split('|').map(d=>{if(d.startsWith('circle:')){const[cx,cy,r]=d.slice(7).split(',');return `<circle cx="${cx}" cy="${cy}" r="${r}"/>`;}return `<path d="${d}"/>`;}).join('')+'</svg>';});const colors={1:'#56a7d6',2:'#eac458',3:'#d5ad48',4:'#919ba8',5:'#71b888',6:'#e987a9',7:'#a58ac8',8:'#df9761'};root.querySelectorAll('.order-pin').forEach(el=>{const n=Number(el.textContent);el.style.setProperty('--pin-color',colors[n]);el.style.color=n===2||n===3?'#66512e':'#fff';});}
const states={normal:{distance:820,progress:48.75,rank:3,phase:'중반 주행',status:'선두권 경쟁',gap:'선두와 <b>3.4 m</b>',comment:'선두권을 따라 페이스를 유지합니다.',order:[1,6,3,2,5,8,4,7],trend:'<i data-icon="dash"></i> 순위 유지',title:'필수 정보는 고정, 중계는 한 줄',copy:'내 주자의 순위는 항상 같은 위치에서 확인합니다. 누적 중계는 기록 창으로 옮깁니다.',caption:'01 / 일반 주행'},skill:{distance:420,progress:73.75,rank:2,phase:'최종 코너',status:'속도 상승 효과 적용 중',gap:'선두와 <b>1.2 m</b>',comment:'페코페코가 속도를 높여 2위로 올라섭니다!',order:[1,3,6,2,5,8,4,7],trend:'<i data-icon="up"></i> 1단계 상승',title:'알림은 두 줄, 내 주자부터',copy:'발동 주체 · 스킬명 · 효과를 한 묶음으로 표시합니다. 연속 발동은 최대 2건을 보여주고 나머지는 기록에 모읍니다.',caption:'02 / 스킬 발동'},sprint:{distance:200,progress:87.5,rank:1,phase:'마지막 직선',status:'선두 유지',gap:'2위와 <b>0.8 m</b>',comment:'남은 거리 200 m! 선두를 지켜냅니다!',order:[3,1,6,2,5,8,4,7],trend:'<i data-icon="up"></i> 선두 진입',title:'막판에는 남은 거리와 역전',copy:'배치와 조작 위치를 유지하면서 거리와 1위를 강조합니다. 순위 변화 문구는 짧게 나타난 뒤 사라지는 요소입니다.',caption:'03 / 마지막 직선'}};
const hud=document.getElementById('hud'),params=new URLSearchParams(location.search),popup=document.getElementById('popup_layer');let state='normal',speed=1,camera=0,skillEnabled=true,commentEnabled=true,previousFocus,timer;
function setState(value){if(!states[value])value='normal';closePopup();state=value;hud.dataset.state=value;hud.classList.remove('state-normal','state-skill','state-sprint');hud.classList.add('state-'+value);const s=states[value];document.getElementById('remaining').textContent=s.distance;document.getElementById('rank').textContent=s.rank;document.getElementById('phase').textContent=s.phase;document.getElementById('status-text').textContent=s.status;document.getElementById('gap').innerHTML=s.gap;document.getElementById('trend').innerHTML=s.trend;document.getElementById('trend').classList.toggle('rising',value!=='normal');document.getElementById('commentary').textContent=s.comment;document.querySelector('.img_progress_fill').style.width=s.progress+'%';document.querySelector('.img_current_point').style.left=s.progress+'%';document.querySelector('[role=progressbar]').setAttribute('aria-valuenow',s.progress);document.getElementById('order-pins').innerHTML=s.order.map(n=>`<span class="order-pin ${n===3?'mine':''}" aria-label="${n===3?'내 주자 ':''}출전번호 ${n}">${n}</span>`).join('');document.querySelector('.group_skill').hidden=value!=='skill'||!skillEnabled;document.querySelector('.obj_rank_event').hidden=value!=='sprint';document.querySelector('.obj_commentary').hidden=!commentEnabled;document.getElementById('point-title').textContent=s.title;document.getElementById('point-copy').textContent=s.copy;document.getElementById('state-caption').textContent=s.caption;document.querySelectorAll('[data-state]').forEach(el=>{if(el.tagName==='BUTTON'){el.classList.toggle('selected',el.dataset.state===value);el.setAttribute('aria-pressed',String(el.dataset.state===value));}});renderIcons();}
function resize(){const capture=document.body.classList.contains('capture'),mobile=innerWidth<=760;const height=mobile&&!capture?Math.max(1280,Math.round(innerHeight*720/innerWidth)):Number(document.getElementById('ratio').value);document.documentElement.style.setProperty('--height',height+'px');hud.classList.toggle('narrow',innerWidth<360);if(capture)return;const scale=mobile?innerWidth/720:Math.min((innerHeight-90)/height,(innerWidth<1080?innerWidth-410:innerWidth-570)/720,.68);const s=Math.max(scale,.24);hud.style.transform=`scale(${s})`;const frame=document.querySelector('.device');frame.style.width=720*s+'px';frame.style.height=height*s+'px';}
function toast(message){clearTimeout(timer);const el=document.getElementById('toast');el.textContent=message;el.hidden=false;timer=setTimeout(()=>el.hidden=true,2300);}
function openPopup(title,content,actions='<button class="action" data-action="close">확인</button>'){previousFocus=document.activeElement;document.getElementById('popup_title').textContent=title;document.getElementById('popup_content').innerHTML=content;document.getElementById('popup_actions').innerHTML=actions;popup.hidden=false;renderIcons(popup);popup.querySelector('button').focus({preventScroll:true});}
function closePopup(){popup.hidden=true;if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true});previousFocus=null;}
const logs=[['현재','내 주자의 현재 순위와 페이스를 확인합니다.'],['스킬 발동','03 · 페코페코의 질주 — 속도 상승'],['스킬 발동','06 · 굳건한 발걸음 — 지구력 효과'],['순위 변화','03번 주자가 3위에서 2위로 올라섭니다.']];
function act(action){const s=states[state];switch(action){case'camera':camera=(camera+1)%3;document.getElementById('camera-label').textContent=['자동 카메라','내 주자','선두 추적'][camera];toast(['자동 카메라','내 주자 추적','선두 주자 추적'][camera]);break;case'speed':speed=speed===1?2:speed===2?4:1;document.getElementById('speed-label').textContent='×'+speed;toast('관전 배속 ×'+speed);break;case'standings':openPopup('현재 순위',s.order.map((n,i)=>`<div class="standing ${n===3?'own':''}"><b>${i+1}</b><span>${String(n).padStart(2,'0')} ${n===3?'기사 · 페코페코':'경쟁 주자'}</span><small>${n===3?'MY':''}</small></div>`).join(''));break;case'runner':openPopup('내 주자',`<div class="detail-row"><span>출전번호</span><strong>03</strong></div><div class="detail-row"><span>캐릭터 · 탈것</span><strong>기사 · 페코페코</strong></div><div class="detail-row"><span>현재 순위</span><strong>${s.rank}위 / 8</strong></div><div class="detail-row"><span>경기 상태</span><strong>${s.status}</strong></div>`);break;case'log':openPopup('중계 · 스킬 기록',[['현재',s.comment],...logs.slice(1,state==='normal'?1:4)].map(r=>`<div class="log-row"><span>${r[0]}</span>${r[1]}</div>`).join(''));break;case'skip':openPopup('결과까지 이동','<p>남은 레이스 연출을 건너뛰고<br>경기 결과를 확인할까요?</p>','<button class="action" data-action="finish">결과 확인</button><button class="action secondary" data-action="close">계속 관전</button>');break;case'finish':openPopup('경기 종료','<div class="finish-banner">FINISH</div><p>경기 결과를 표시하는 다음 화면으로 연결합니다.</p>','<button class="action" data-action="close">시안으로 돌아가기</button>');break;case'menu':openPopup('관전 메뉴',`<label class="setting">스킬 알림<input id="setting-skill" type="checkbox" ${skillEnabled?'checked':''}></label><label class="setting">중계 문구<input id="setting-comment" type="checkbox" ${commentEnabled?'checked':''}></label>`,'<button class="action" data-action="settings">적용하고 계속 관전</button><button class="action secondary" data-action="pause">일시정지</button>');break;case'settings':skillEnabled=document.getElementById('setting-skill').checked;commentEnabled=document.getElementById('setting-comment').checked;closePopup();setState(state);break;case'pause':openPopup('일시정지','<p>잠시 관전을 멈췄습니다.</p>','<button class="action" data-action="close">계속 관전</button>');break;case'close':closePopup();break;}}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.state)setState(b.dataset.state);else if(b.dataset.action)act(b.dataset.action);});document.addEventListener('keydown',event=>{if(!popup.hidden){if(event.key==='Escape')closePopup();if(event.key==='Tab'){const buttons=[...popup.querySelectorAll('button,input')],first=buttons[0],last=buttons.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}}else if(['1','2','3'].includes(event.key))setState(['normal','skill','sprint'][Number(event.key)-1]);});
function showCutin(on){hud.classList.toggle('show-cutin',on);document.querySelector('.group_cutin').hidden=!on;document.getElementById('cutin').checked=on;}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="skip-cutin"]')){showCutin(false);setState('skill');}if(e.target.closest('.review [data-state]'))showCutin(false);});
document.getElementById('plain').onchange=e=>hud.classList.toggle('plain',e.target.checked);document.getElementById('guides').onchange=e=>hud.classList.toggle('show-guides',e.target.checked);document.getElementById('cutin').onchange=e=>showCutin(e.target.checked);document.getElementById('ratio').onchange=resize;window.addEventListener('resize',resize);if(params.has('capture'))document.body.classList.add('capture');if(params.has('overlay'))document.body.classList.add('overlay');if(params.has('plain'))hud.classList.add('plain');if(params.has('guides'))hud.classList.add('show-guides');if(params.get('height')==='1600')document.getElementById('ratio').value='1600';setState(params.get('state')||'normal');showCutin(params.has('cutin'));resize();
